    "home.h3.integration": "Integration",
    "home.p.receive-a-written-summary-and-optional": "Få en skriftlig sammanfattning och valfri uppföljning för att fördjupa din förståelse över tid.",
    "home.section-label.client-reflections": "Kundreflektioner",
