    "page.connType.mirror-opposite.h2.find-mirror-opposite-matches": "Find Mirror Opposite Matches",
    "page.connType.mirror-opposite.p.calculate-your-four-totem-animals-then": "Calculate your four totem animals, then browse the opt-in directory for people who share this connection type with you.",
    "page.connType.mirror-opposite.btn.totem-connections-directory": "Totem Connections Directory",
    "page.connType.mirror-opposite.btn.totem-animals-calculator": "Totem Animals Calculator",
    "page.connType.values-trine.section-label.connection-type": "Connection Type",
    "page.connType.values-trine.h1.values-trine": "Values Trine",
    "page.connType.values-trine.p.shared-value-both-animals-belong-to": "Shared value — both animals belong to the same Values Triangle, so you often speak the same language when it comes to life's priorities.",
    "page.connType.values-trine.p.totem-connections": "<a href=\"connections.html?v=20260807\">← Totem Connections</a>",
    "page.connType.values-trine.p.shared-value-both-animals-belong-to.2": "Shared value — both animals belong to the same Values Triangle: Power & Prestige, Security & Stability, Inspiration & Idealism, or Peace & Harmony. These connections are people who speak the same language as you, values-wise. They have similar priorities when it comes to how to go about dealing with life — whether that be the pursuit of power and craftsmanship in a trade, or the pursuit of peace and an easy-going lifestyle. These are people you don't have to explain yourself to very often, because they're already on the same page as you, so it can be great for any type of relationship: business or pleasure, family or friendship. Cool runnings :)",
    "page.connType.values-trine.h3.other-connection-types": "Other connection types",
    "page.connType.values-trine.li.rainbow": "<a href=\"connection-rainbow.html?v=20260807\">Rainbow</a>",
