    "page.connType.values-trine.h2.find-values-trine-matches": "Find Values Trine Matches",
    "page.connType.values-trine.p.calculate-your-four-totem-animals-then": "Calculate your four totem animals, then browse the opt-in directory for people who share this connection type with you.",
    "page.connType.values-trine.btn.totem-connections-directory": "Totem Connections Directory",
